import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), k = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // A cut between i and i+1 adds a[i] + a[i+1] to the cost.
        int m = n - 1;
        long[] weights = new long[m];
        for (int i = 0; i < m; i++) weights[i] = a[i] + a[i + 1];
        Arrays.sort(weights);
        long base = a[0] + a[n - 1], smallest = base, largest = base;
        for (int i = 0; i < k - 1; i++) {
            smallest += weights[i];
            largest += weights[m - 1 - i];
        }
        System.out.println(smallest + " " + largest);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"sort"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k := nextInt(), nextInt()
	a := make([]int, n)
	for i := range a {
		a[i] = nextInt()
	}
	// A cut between i and i+1 adds a[i] + a[i+1] to the cost.
	m := n - 1
	weights := make([]int, m)
	for i := 0; i < m; i++ {
		weights[i] = a[i] + a[i+1]
	}
	sort.Ints(weights)
	base := a[0] + a[n-1]
	smallest, largest := base, base
	for i := 0; i < k-1; i++ {
		smallest += weights[i]
		largest += weights[m-1-i]
	}
	fmt.Println(smallest, largest)
}
